14	// On-disk checkpoint chain.
15	//
16	// A checkpoint freezes one complete committed state so reopening can seed
17	// memory from it and replay only the write-ahead log written afterwards.
18	// Rather than rewriting one monolithic file for every checkpoint, this
19	// version keeps a chain of self-describing layers inside the checkpoint
20	// directory (checkpointDirName):
21	//
22	//   - Layer 0 (the base) holds the complete state at its capture time.
23	//   - Every later layer is a delta covering only the keys touched by commits
24	//     strictly after the layer it builds on.
25	//
26	// Reopen loads layers in index order, stopping at the last complete, intact
27	// layer of one unbroken chain, then replays the WAL tail from that layer's
28	// cut. Any layer that is missing, truncated, checksum-bad, version-unknown or
29	// whose chain linkage is broken rejects that layer and every later one as a
30	// whole: recovery falls back to the previous usable layer, or to a from-WAL
31	// reopen when the base itself is unusable.
32	//
33	// Each layer file is independently an all-or-nothing artifact: it is built
34	// under a temporary name, forced whole with one fsync, then atomically
35	// renamed into place. A layer's content hashes (CRC-32) link it to the layer
36	// before it, so deleting or replacing one layer invalidates the suffix; the
37	// valid prefix is always usable on its own.
38	//
39	// Layer layout (all integers little-endian):
40	//
41	//	magic     uint32   checkpointMagic
42	//	version   uint32   checkpointVersion2
43	//	index     uint32   this layer's position; 0 for the base
44	//	prevCRC   uint32   content CRC of the previous layer (0 for the base)
45	//	seq       uint64   highest commit sequence covered at capture time
46	//	snapshots uint64   cumulative number of snapshots covered
47	//	offset    uint64   WAL byte offset of the cut: frames at or past this
48	//	                  offset form the post-layer tail replayed on reopen
49	//	count     uint32   number of entries that follow
50	//	entries   [count]entry
51	//	crc       uint32   IEEE CRC-32 of every preceding byte of this file
52	//
53	// One entry is a flags byte (0 = put, 1 = tombstone), a uint32 key length, a
54	// uint32 value length, the entry's commit sequence (uint64), the key, then the
55	// value. The base lists every live key exactly once; a delta lists only
56	// changed keys, with each key appearing at most once.
57	//
58	// The cut offset is measured in the WAL the chain is paired with. A checkpoint
59	// never modifies the WAL; compaction (the only WAL rewrite) first durably
60	// withdraws the chain and then re-establishes surviving layers against the
61	// replacement log before its rename becomes state, so a layer is never read
62	// against a different WAL than the one its cut describes.
63	const (
64		checkpointDirName = "ckpt"
65	
66		// checkpointName/checkpointTmpName are the version-1 single-file layout.
67		// They stay readable so a directory written by the old version reopens
68		// unchanged; the first checkpoint taken by this version upgrades it into
69		// the layered directory and removes the old file.
70		checkpointName    = "snapshot.ckpt"
71		checkpointTmpName = "snapshot.ckpt.tmp"
72	
73		// layerTmpSuffix stages a layer while it is built; it never appears under a
74		// final layer name. A file carrying it is crash debris swept on the next
75		// open.
76		layerTmpSuffix = ".tmp"
77	
78		checkpointMagic    uint32 = 0x504b4353 // bytes "SCKP"
79		checkpointVersion1 uint32 = 1
80		checkpointVersion2 uint32 = 2
81	
82		checkpointHeaderSize      = 4 + 4 + 8 + 8 + 8 + 4
83		layer2HeaderSize          = 4 + 4 + 4 + 4 + 8 + 8 + 8 + 4
84		checkpointEntrySize       = 1 + 4 + 4 + 8 // flags, keyLen, valLen, seq
85		ckptFlagPut          byte = 0
86		ckptFlagDelete       byte = 1
87	)
88	
89	// checkpointEntry is one entry in a layer: a terminal key state.
90	type checkpointEntry struct {
91		key     string
92		value   []byte
93		seq     uint64
94		present bool
95	}
96	
97	// layerState is the decoded content of one validated layer plus the content
98	// hash that links the next layer back to it.
99	type layerState struct {
100		index   uint32
101		prevCRC uint32
102		entries []checkpointEntry
103		offset  int64 // WAL cut of this layer
104		seq     uint64
105		snaps   uint64
106		crc     uint32 // content CRC of this layer (the terminal checksum it carries)
107	}
108	
109	// capturedLayer is what Checkpoint serializes for one new layer.
110	type capturedLayer struct {
111		index   uint32
112		prevCRC uint32
113		entries []checkpointEntry
114		offset  uint64
115		seq     uint64
116		snaps   uint64
117	}
118	
119	func layerFileName(index uint32) string {
120		return filepath.Join(checkpointDirName, formatLayerIndex(index))
121	}
122	
123	func layerTmpName(index uint32) string {
124		return layerFileName(index) + layerTmpSuffix
125	}
126	
127	// formatLayerIndex renders a layer index as a fixed-width, zero-padded name so
128	// the on-disk listing is already in chain order.
129	func formatLayerIndex(index uint32) string {
130		const digits = "0123456789"
131		buf := make([]byte, 10)
132		for i := len(buf) - 1; i >= 0; i-- {
133			buf[i] = digits[index%10]
134			index /= 10
135		}
136		return string(buf) + ".ckpt"
137	}
138	
139	// parseLayerIndex is the inverse of formatLayerIndex. ok is false for names
140	// that are not final layer files.
141	func parseLayerIndex(name string) (uint32, bool) {
142		if len(name) != len("0000000000.ckpt") || name[10:] != ".ckpt" {
143			return 0, false
144		}
145		var n uint32
146		for i := 0; i < 10; i++ {
147			c := name[i]
148			if c < '0' || c > '9' {
149				return 0, false
150			}
151			n = n*10 + uint32(c-'0')
152		}
153		return n, true
154	}
155	
156	func checkpointDirPath(dir string) string {
157		return filepath.Join(dir, checkpointDirName)
158	}
159	
160	// errCheckpointRejected marks any validation failure. It is never surfaced to
161	// the caller of Open: a rejected layer is an expected outcome handled by
162	// falling back to a shorter chain or a WAL-only reopen.
163	func errCheckpointRejected(err error) error {
164		return errors.Join(errors.New("snapshot: rejecting checkpoint layer"), err)
165	}
166	
167	// captureView serializes the terminal state of a view, tombstones included
168	// (a base layer must reproduce deletions, not just live values). Entries are
169	// sorted by key for a canonical encoding and values are copied so later
170	// commits cannot mutate the bytes being written.
171	func captureView(v *view) []checkpointEntry {
172		var entries []checkpointEntry
173		v.rangeEach(func(k string, n *node) bool {
174			e := checkpointEntry{key: k, present: n.present, seq: n.seq}
175			if n.present {
176				e.value = cloneBytes(n.value)
177			}
178			entries = append(entries, e)
179			return true
180		})
181		sort.Slice(entries, func(i, j int) bool { return entries[i].key < entries[j].key })
182		return entries
183	}
184	
185	// captureDelta serializes only the keys in dirtyKeys, reading their terminal
186	// state from v. Absent keys are skipped: a delta never carries a "never
187	// existed" entry. Output is sorted by key and de-duplicated.
188	func captureDelta(v *view, dirtyKeys []string) []checkpointEntry {
189		seen := make(map[string]struct{}, len(dirtyKeys))
190		keys := make([]string, 0, len(dirtyKeys))
191		for _, k := range dirtyKeys {
192			if _, dup := seen[k]; dup {
193				continue
194			}
195			seen[k] = struct{}{}
196			keys = append(keys, k)
197		}
198		entries := make([]checkpointEntry, 0, len(keys))
199		sort.Strings(keys)
200		for _, k := range keys {
201			n := v.lookup(k)
202			if n == nil {
203				continue
204			}
205			e := checkpointEntry{key: k, present: n.present, seq: n.seq}
206			if n.present {
207				e.value = cloneBytes(n.value)
208			}
209			entries = append(entries, e)
210		}
211		return entries
212	}
213	
214	// writeLayerFile serializes layer to relName freshly (O_EXCL), forces the
215	// whole file with one fsync and closes it. It never touches a live layer; the
216	// caller renames it into place only once this succeeds. It returns the
217	// content CRC written into the terminal field, which links the next layer.
218	func writeLayerFile(dir, relName string, layer capturedLayer) (crc uint32, err error) {
219		path := filepath.Join(dir, relName)
220		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
221		if err != nil {
222			return 0, err
223		}
224		defer func() {
225			if err != nil {
226				f.Close()
227				os.Remove(path)
228			}
229		}()
230	
231		w := bufio.NewWriter(f)
232		head := make([]byte, layer2HeaderSize)
233		binary.LittleEndian.PutUint32(head[0:4], checkpointMagic)
234		binary.LittleEndian.PutUint32(head[4:8], checkpointVersion2)
235		binary.LittleEndian.PutUint32(head[8:12], layer.index)
236		binary.LittleEndian.PutUint32(head[12:16], layer.prevCRC)
237		binary.LittleEndian.PutUint64(head[16:24], layer.seq)
238		binary.LittleEndian.PutUint64(head[24:32], layer.snaps)
239		binary.LittleEndian.PutUint64(head[32:40], layer.offset)
240		binary.LittleEndian.PutUint32(head[40:44], uint32(len(layer.entries)))
241	
242		h := crc32.NewIEEE()
243		if _, err = w.Write(head); err != nil {
244			return 0, err
245		}
246		h.Write(head)
247	
248		ehdr := make([]byte, checkpointEntrySize)
249		for _, e := range layer.entries {
250			if len(e.key) > maxRecord || len(e.value) > maxRecord {
251				return 0, errors.New("snapshot: checkpoint entry too large")
252			}
253			if e.present {
254				ehdr[0] = ckptFlagPut
255			} else {
256				ehdr[0] = ckptFlagDelete
257			}
258			binary.LittleEndian.PutUint32(ehdr[1:5], uint32(len(e.key)))
259			binary.LittleEndian.PutUint32(ehdr[5:9], uint32(len(e.value)))
260			binary.LittleEndian.PutUint64(ehdr[9:17], e.seq)
261			if _, err = w.Write(ehdr); err != nil {
262				return 0, err
263			}
264			h.Write(ehdr)
265			if _, err = io.WriteString(w, e.key); err != nil {
266				return 0, err
267			}
268			h.Write([]byte(e.key))
269			if len(e.value) > 0 {
270				if _, err = w.Write(e.value); err != nil {
271					return 0, err
272				}
273				h.Write(e.value)
274			}
275		}
276	
277		crc = h.Sum32()
278		var crcb [crcSize]byte
279		binary.LittleEndian.PutUint32(crcb[:], crc)
280		if _, err = w.Write(crcb[:]); err != nil {
281			return 0, err
282		}
283		if err = w.Flush(); err != nil {
284			return 0, err
285		}
286		if err = f.Sync(); err != nil {
287			return 0, err
288		}
289		if err = f.Close(); err != nil {
290			return 0, err
291		}
292		return crc, nil
293	}
294	
295	// loadLayer reads and fully validates one layer file. It returns the decoded
296	// state including the terminal content hash. Any defect (missing file is the
297	// caller's concern, truncation, bad magic/version, bad checksum, malformed
298	// field, duplicated key, trailing bytes) yields a rejection error.
299	func loadLayer(dir, relName string, wantIndex uint32) (layerState, error) {
300		f, err := os.Open(filepath.Join(dir, relName))
301		if err != nil {
302			return layerState{}, err
303		}
304		defer f.Close()
305	
306		reject := func(err error) (layerState, error) {
307			return layerState{}, errCheckpointRejected(err)
308		}
309	
310		r := bufio.NewReader(f)
311		h := crc32.NewIEEE()
312	
313		head := make([]byte, layer2HeaderSize)
314		if _, err := io.ReadFull(r, head); err != nil {
315			return reject(err)
316		}
317		h.Write(head)
318	
319		magic := binary.LittleEndian.Uint32(head[0:4])
320		version := binary.LittleEndian.Uint32(head[4:8])
321		index := binary.LittleEndian.Uint32(head[8:12])
322		if magic != checkpointMagic || version != checkpointVersion2 {
323			return reject(errors.New("snapshot: unknown checkpoint format"))
324		}
325		if index != wantIndex {
326			return reject(errors.New("snapshot: checkpoint layer index out of order"))
327		}
328		var st layerState
329		st.index = index
330		st.prevCRC = binary.LittleEndian.Uint32(head[12:16])
331		st.seq = binary.LittleEndian.Uint64(head[16:24])
332		st.snaps = binary.LittleEndian.Uint64(head[24:32])
333		off := binary.LittleEndian.Uint64(head[32:40])
334		count := binary.LittleEndian.Uint32(head[40:44])
335		if count > maxRecord {
336			return reject(errors.New("snapshot: checkpoint entry count out of range"))
337		}
338		st.offset = int64(off)
339		if uint64(st.offset) != off || st.offset < 0 {
340			return reject(errors.New("snapshot: checkpoint offset out of range"))
341		}
342	
343		st.entries = make([]checkpointEntry, 0, count)
344		ehdr := make([]byte, checkpointEntrySize)
345		seen := make(map[string]bool, count)
346		for i := uint32(0); i < count; i++ {
347			if _, err := io.ReadFull(r, ehdr); err != nil {
348				return reject(err)
349			}
350			h.Write(ehdr)
351			flag := ehdr[0]
352			keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
353			valLen := binary.LittleEndian.Uint32(ehdr[5:9])
354			seq := binary.LittleEndian.Uint64(ehdr[9:17])
355			if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
356				keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
357				(flag == ckptFlagDelete && valLen != 0) {
358				return reject(errors.New("snapshot: malformed checkpoint entry"))
359			}
360			body := make([]byte, int(keyLen)+int(valLen))
361			if _, err := io.ReadFull(r, body); err != nil {
362				return reject(err)
363			}
364			h.Write(body)
365			key := string(body[:keyLen])
366			if seen[key] {
367				return reject(errors.New("snapshot: duplicate key in checkpoint layer"))
368			}
369			seen[key] = true
370			e := checkpointEntry{key: key, seq: seq, present: flag == ckptFlagPut}
371			if e.present {
372				e.value = cloneBytes(body[keyLen:])
373			}
374			st.entries = append(st.entries, e)
375		}
376	
377		var crcb [crcSize]byte
378		if _, err := io.ReadFull(r, crcb[:]); err != nil {
379			return reject(err)
380		}
381		st.crc = binary.LittleEndian.Uint32(crcb[:])
382		if st.crc != h.Sum32() {
383			return reject(errors.New("snapshot: checkpoint checksum mismatch"))
384		}
385		if b, err := r.ReadByte(); err == nil {
386			_ = b
387			return reject(errors.New("snapshot: checkpoint layer has trailing bytes"))
388		} else if !errors.Is(err, io.EOF) {
389			return reject(err)
390		}
391		return st, nil
392	}
393	
394	// loadCheckpointChain discovers, validates and loads the layered chain. It
395	// returns the loaded layers (a dense prefix 0..n-1), the index of the next
396	// layer to write, and the content hash the new layer must link to. An absent
397	// or unusable chain is not an error: layers is empty and the caller either
398	// tries the version-1 file or reopens from the WAL.
399	//
400	// Corruption in layer k (or a gap before it) makes layer k and every later
401	// layer unusable. The caller is responsible for removing the rejected suffix;
402	// this function only reports the boundary.
403	func loadCheckpointChain(dir string) (layers []layerState, nextIndex uint32, prevCRC uint32, err error) {
404		entries, rerr := os.ReadDir(checkpointDirPath(dir))
405		if rerr != nil {
406			if errors.Is(rerr, os.ErrNotExist) {
407				return nil, 0, 0, nil
408			}
409			return nil, 0, 0, rerr
410		}
411		// Collect final layer files only; temp debris and unrelated files are
412		// ignored by chain assembly and swept elsewhere.
413		have := make(map[uint32]string)
414		for _, e := range entries {
415			if e.IsDir() {
416				continue
417			}
418			if idx, ok := parseLayerIndex(e.Name()); ok {
419				have[idx] = filepath.Join(checkpointDirName, e.Name())
420			}
421		}
422		var expectCRC uint32
423		for index := uint32(0); ; index++ {
424			rel, ok := have[index]
425			if !ok {
426				return layers, index, expectCRC, nil
427			}
428			st, lerr := loadLayer(dir, rel, index)
429			if lerr != nil {
430				return layers, index, expectCRC, nil
431			}
432			if index == 0 {
433				// Base must stand alone.
434				if st.prevCRC != 0 {
435					return layers, index, expectCRC, nil
436				}
437			} else if st.prevCRC != expectCRC {
438				// Suffix no longer links to the prefix: reject from here.
439				return layers, index, expectCRC, nil
440			}
441			layers = append(layers, st)
442			expectCRC = st.crc
443		}
444	}
445	
446	// loadLegacyCheckpoint reads the version-1 single-file checkpoint. A missing
447	// file reports ok=false with nil error. It exists solely to reopen directories
448	// written by the old single-file version; the first new checkpoint upgrades
449	// them.
450	func loadLegacyCheckpoint(dir string) (st capturedState, ok bool, err error) {
451		f, rerr := os.Open(filepath.Join(dir, checkpointName))
452		if rerr != nil {
453			if errors.Is(rerr, os.ErrNotExist) {
454				return capturedState{}, false, nil
455			}
456			return capturedState{}, false, rerr
457		}
458		defer f.Close()
459	
460		reject := func(err error) (capturedState, bool, error) {
461			return capturedState{}, false, errCheckpointRejected(err)
462		}
463	
464		r := bufio.NewReader(f)
465		h := crc32.NewIEEE()
466	
467		head := make([]byte, checkpointHeaderSize)
468		if _, err := io.ReadFull(r, head); err != nil {
469			return reject(err)
470		}
471		h.Write(head)
472	
473		magic := binary.LittleEndian.Uint32(head[0:4])
474		version := binary.LittleEndian.Uint32(head[4:8])
475		if magic != checkpointMagic || version != checkpointVersion1 {
476			return reject(errors.New("snapshot: unknown checkpoint format"))
477		}
478		st.seq = binary.LittleEndian.Uint64(head[8:16])
479		st.snaps = binary.LittleEndian.Uint64(head[16:24])
480		off := binary.LittleEndian.Uint64(head[24:32])
481		count := binary.LittleEndian.Uint32(head[32:36])
482		if count > maxRecord {
483			return reject(errors.New("snapshot: checkpoint entry count out of range"))
484		}
485		st.offset = int64(off)
486		if uint64(st.offset) != off {
487			return reject(errors.New("snapshot: checkpoint offset out of range"))
488		}
489	
490		st.entries = make([]checkpointEntry, 0, count)
491		ehdr := make([]byte, checkpointEntrySize)
492		seen := make(map[string]bool, count)
493		for i := uint32(0); i < count; i++ {
494			if _, err := io.ReadFull(r, ehdr); err != nil {
495				return reject(err)
496			}
497			h.Write(ehdr)
498			flag := ehdr[0]
499			keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
500			valLen := binary.LittleEndian.Uint32(ehdr[5:9])
501			seq := binary.LittleEndian.Uint64(ehdr[9:17])
502			if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
503				keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
504				(flag == ckptFlagDelete && valLen != 0) {
505				return reject(errors.New("snapshot: malformed checkpoint entry"))
506			}
507			body := make([]byte, int(keyLen)+int(valLen))
508			if _, err := io.ReadFull(r, body); err != nil {
509				return reject(err)
510			}
511			h.Write(body)
512			key := string(body[:keyLen])
513			if seen[key] {
514				return reject(errors.New("snapshot: duplicate key in checkpoint"))
515			}
516			seen[key] = true
517			e := checkpointEntry{key: key, seq: seq, present: flag == ckptFlagPut}
518			if e.present {
519				e.value = cloneBytes(body[keyLen:])
520			}
521			st.entries = append(st.entries, e)
522		}
523	
524		var crcb [crcSize]byte
525		if _, err := io.ReadFull(r, crcb[:]); err != nil {
526			return reject(err)
527		}
528		if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() {
529			return reject(errors.New("snapshot: checkpoint checksum mismatch"))
530		}
531		if b, err := r.ReadByte(); err == nil {
532			_ = b
533			return reject(errors.New("snapshot: checkpoint has trailing bytes"))
534		} else if !errors.Is(err, io.EOF) {
535			return reject(err)
536		}
537		return st, true, nil
538	}
539	
540	// capturedState is a legacy version-1 checkpoint's full content.
541	type capturedState struct {
542		entries []checkpointEntry
543		offset  int64
544		seq     uint64
545		snaps   uint64
546	}
547	
548	// installLayer builds one complete layer in its temp name and atomically
549	// renames it into place, forcing the checkpoint directory afterwards. It
550	// touches neither the WAL nor the live writer: a crash at any point leaves
551	// either the previous chain or the chain extended by one complete layer.
552	func installLayer(dir string, layer capturedLayer) error {
553		cdir := checkpointDirPath(dir)
554		if err := os.MkdirAll(cdir, 0o700); err != nil {
555			return err
556		}
557		tmp := layerTmpName(layer.index)
558		final := layerFileName(layer.index)
559		if err := os.Remove(filepath.Join(dir, tmp)); err != nil && !errors.Is(err, os.ErrNotExist) {
560			return err
561		}
562		if _, err := writeLayerFile(dir, tmp, layer); err != nil {
563			return err
564		}
565		if err := os.Rename(filepath.Join(dir, tmp), filepath.Join(dir, final)); err != nil {
566			os.Remove(filepath.Join(dir, tmp))
567			return err
568		}
569		// A crash before this force lands either the chain without the new layer
570		// or with it fully present; both reopen on their own.
571		return syncDirectory(cdir)
572	}
573	
574	// removeLayerFrom deletes layer index and any temp for it, best effort. Used
575	// while retiring a rejected suffix and during compaction's chain rebuild.
576	func removeLayerFrom(dir string, index uint32) {
577		os.Remove(filepath.Join(dir, layerFileName(index)))
578		os.Remove(filepath.Join(dir, layerTmpName(index)))
579	}
580	
581	// sweepCheckpointDebris removes every half-built layer temp in the checkpoint
582	// directory (staging debris from a kill between the build and the rename) and
583	// the legacy version-1 temp. Final layer files and the WAL are untouched.
584	func sweepCheckpointDebris(dir string) error {
585		cdir := checkpointDirPath(dir)
586		entries, err := os.ReadDir(cdir)
587		if err != nil {
588			if errors.Is(err, os.ErrNotExist) {
589				return removeLegacyTemp(dir)
590			}
591			return err
592		}
593		for _, e := range entries {
594			if e.IsDir() {
595				continue
596			}
597			name := e.Name()
598			if len(name) > len(layerTmpSuffix) && name[len(name)-len(layerTmpSuffix):] == layerTmpSuffix {
599				if err := os.Remove(filepath.Join(cdir, name)); err != nil && !errors.Is(err, os.ErrNotExist) {
600					return err
601				}
602			}
603		}
604		return removeLegacyTemp(dir)
605	}
606	
607	// removeLegacyTemp deletes a half-built version-1 checkpoint temp.
608	func removeLegacyTemp(dir string) error {
609		err := os.Remove(filepath.Join(dir, checkpointTmpName))
610		if err != nil && !errors.Is(err, os.ErrNotExist) {
611			return err
612		}
613		return nil
614	}
615	
616	// removeRejectedChainSuffix deletes every layer at or after firstBad and
617	// forces the checkpoint directory, so a broken layer and the layers that
618	// depend on it neither linger nor occupy space. The valid prefix and the WAL
619	// remain complete sources of truth.
620	func removeRejectedChainSuffix(dir string, firstBad uint32) {
621		cdir := checkpointDirPath(dir)
622		for index := firstBad; ; index++ {
623			if _, err := os.Stat(filepath.Join(dir, layerFileName(index))); err != nil {
624				break
625			}
626			removeLayerFrom(dir, index)
627		}
628		_ = syncDirectory(cdir)
629	}
630	
631	// removeRejectedLegacy discards a version-1 checkpoint that failed validation.
632	func removeRejectedLegacy(dir string) {
633		if err := os.Remove(filepath.Join(dir, checkpointName)); err != nil {
634			return
635		}
636		_ = syncDirectory(dir)
637	}
638	
639	// removeLegacyCheckpoint withdraws the version-1 file during an upgrade to the
640	// layered layout and forces both directories so the removal is durable before
641	// the new base is relied upon.
642	func removeLegacyCheckpoint(dir string) error {
643		path := filepath.Join(dir, checkpointName)
644		if _, err := os.Stat(path); err != nil {
645			if errors.Is(err, os.ErrNotExist) {
646				return nil
647			}
648			return err
649		}
650		if err := os.Remove(path); err != nil {
651			return err
652		}
653		if err := syncDirectory(dir); err != nil {
654			return err
655		}
656		return nil
657	}
658	
659	// retireChain durably withdraws the entire layered chain (and any legacy
660	// checkpoint) while the WAL it pairs with is still in place. Compaction calls
661	// it before the WAL rename so a layer can never be found against a different
662	// WAL. The checkpoint directory itself is removed when empty. Its absence is
663	// normal and not an error.
664	func retireChain(dir string) error {
665		if err := removeLegacyCheckpoint(dir); err != nil {
666			return err
667		}
668		cdir := checkpointDirPath(dir)
669		if err := os.RemoveAll(cdir); err != nil {
670			return err
671		}
672		return syncDirectory(dir)
673	}
674	
675	// chainInfo is a compact view of the on-disk chain used by the store.
676	type chainInfo struct {
677		layers    []layerState
678		nextIndex uint32
679		prevCRC   uint32
680	}
681	
682	// readChain loads the layered chain. A missing chain returns an empty info.
683	func readChain(dir string) (chainInfo, error) {
684		layers, nextIndex, prevCRC, err := loadCheckpointChain(dir)
685		if err != nil {
686			return chainInfo{}, err
687		}
688		return chainInfo{layers: layers, nextIndex: nextIndex, prevCRC: prevCRC}, nil
689	}
690	
691	// pruneRejectedChainFiles removes every final layer file whose index is at or
692	// beyond keep: those layers are missing, corrupt, version-unknown or unlinked
693	// to the valid prefix and are rejected as a whole. The valid prefix (indices
694	// below keep) and the WAL are left intact. It is best effort and idempotent.
695	func pruneRejectedChainFiles(dir string, keep int) {
696		entries, err := os.ReadDir(checkpointDirPath(dir))
697		if err != nil {
698			return
699		}
700		var bad []uint32
701		for _, e := range entries {
702			if e.IsDir() {
703				continue
704			}
705			if idx, ok := parseLayerIndex(e.Name()); ok && int(idx) >= keep {
706				bad = append(bad, idx)
707			}
708		}
709		if len(bad) == 0 {
710			return
711		}
712		sort.Slice(bad, func(i, j int) bool { return bad[i] < bad[j] })
713		removeRejectedChainSuffix(dir, bad[0])
714	}
715	
716	// sweepStagedChain removes a replacement-chain staging directory left by a
717	// compaction killed before it was promoted. Only checkpointDirName is ever
718	// read, so a stale staged directory is pure debris.
719	func sweepStagedChain(dir string) error {
720		err := os.RemoveAll(filepath.Join(dir, stagedChainDir))
721		if err != nil && !errors.Is(err, os.ErrNotExist) {
722			return err
723		}
724		return nil
725	}
