231	// newCursor materializes the cursor's ordered key list once, at open time,
232	// and registers it so compaction retains its versions.
233	func (s *Store) newCursor(v *view, start, end string) *Cursor {
234		c := newCursorPinned(s, v, start, end)
235		s.registerCursor(c)
236		return c
237	}
238	
239	func newCursorPinned(st *Store, v *view, start, end string) *Cursor {
240		return &Cursor{
241			store: st,
242			v:     v,
243			start: start,
244			end:   end,
245			keys:  presentKeys(v, start, end),
246		}
247	}
