249	// newEmptyCursor returns a never-erroring cursor over nothing, used when a
250	// cursor is opened over an empty/closed view. It pins no versions.
251	func newEmptyCursor() *Cursor {
252		return &Cursor{v: newView(nil), keys: nil}
253	}
254	
255	// ---- ordered reads over immutable views ----
256	
257	func scanView(v *view, start, end string, limit int) []KVPair {
258		keys := presentKeys(v, start, end)
259		if limit > 0 && len(keys) > limit {
260			keys = keys[:limit]
261		}
262		out := make([]KVPair, 0, len(keys))
263		for _, k := range keys {
264			n := v.lookup(k)
265			out = append(out, KVPair{Key: k, Value: cloneBytes(n.value)})
