271	// Go's string ordering is unsigned byte ordering on the raw contents.
272	func presentKeys(v *view, start, end string) []string {
273		var keys []string
274		v.rangeEach(func(k string, n *node) bool {
275			if n == nil || !n.present {
276				return true
277			}
278			if start != "" && k < start {
279				return true
280			}
281			if end != "" && k >= end {
282				return true
283			}
284			keys = append(keys, k)
285			return true
286		})
