```go
func backupSegmentName(index uint32) string {
	const digits = "0123456789"
	buf := make([]byte, len("backup-0000000000.seg"))
	copy(buf, "backup-")
	n := index
	for i := len("backup-") + 9; i >= len("backup-"); i-- {
		buf[i] = digits[n%10]
		n /= 10
	}
	copy(buf[len(buf)-4:], ".seg")
	return string(buf)
}
