parse:

```go
func parseBackupSegmentName(name string) (uint32, bool) {
	const prefix = "backup-"
	const suffix = ".seg"
	if len(name) != len(prefix)+10+len(suffix) || name[:len(prefix)] != prefix || name[len(name)-len(suffix):] != suffix {
		return 0, false
	}
	var n uint32
	for i := len(prefix); i < len(prefix)+10; i++ {
		c := name[i]
		if c < '0' || c > '9' { return 0, false }
		n = n*10 + uint32(c-'0')
	}
	return n, true
}
