func exportBackup(dir string, v *view, seq, snaps uint64) error {
	if dir == "" {
		return errEmptyPath
	}
	info, err := os.Stat(dir)
	if err == nil {
		if !info.IsDir() {
			return errNotDir
		}
	} else {
		if !errors.Is(err, fs.ErrNotExist) {
			return err
		}
		if err := os.MkdirAll(dir, 0o700); err != nil {
			return err
		}
	}
	if err := sweepBackupDebris(dir); err != nil {
		return err
	}

	// Collect the key order once. Keys are shared with the view's maps, so
	// this allocates only string headers for the touched keys; values are
	// streamed straight out of the immutable nodes, never cloned in bulk.
	var keys []string
	v.rangeEach(func(k string, _ *node) bool {
		keys = append(keys, k)
		return true
	})
	sort.Strings(keys)

	segments := uint32(1)
	if len(keys) > 0 {
		segments = uint32((len(keys) + backupSegmentEntries - 1) / backupSegmentEntries)
	}

	var written []string
	fail := func(err error) error {
		for _, name := range written {
			os.Remove(filepath.Join(dir, name))
		}
		return err
	}
	for index := uint32(0); index < segments; index++ {
		lo := int(index) * backupSegmentEntries
		hi := lo + backupSegmentEntries
		if hi > len(keys) {
			hi = len(keys)
		}
		name, werr := writeBackupSegment(dir, index, segments, seq, snaps, v, keys[lo:hi])
		if werr != nil {
			return fail(werr)
		}
		written = append(written, name)
	}
	pruneStaleBackupSegments(dir, segments)
	return syncDirectory(dir)
}
