			encErr = l.encodeFrameSeq(opDeleteSeq, e.key, e.seq, nil)
		}
		if encErr != nil { return fail(encErr) }
	}
	if snaps > 0 {
		var v [metaValueSize]byte
		binary.LittleEndian.PutUint64(v[:], snaps)
		if err := l.encodeFrame(opMeta, "", v[:]); err != nil { return fail(err) }
	}
	if err := l.w.Flush(); err != nil { return fail(err) }
	if err := f.Sync(); err != nil { return fail(err) }
	if err := f.Close(); err != nil {
		os.Remove(tmpPath)
		return err
	}
	if err := os.Rename(tmpPath, filepath.Join(dir, walName)); err != nil {
		os.Remove(tmpPath)
		return err
	}
	return syncDirectory(dir)
}
