	}
	rs2 := openStore(t, rdirOf(rs))
	_ = rs2
}

// rdirOf is unused; kept minimal helpers below instead.
func rdirOf(s *Store) string { return s.dir }

func TestBackupRestoreEmptyStore(t *testing.T) {
