func TestBackupFromSnapshotWatermark(t *testing.T) {
	s := openStore(t, tempDir(t))
	if err := s.Put("a", []byte("one")); err != nil {
		t.Fatal(err)
	}
	snap, err := s.Snapshot()
	if err != nil {
