// collapse merges every overlay above the view's flat base into a single
// overlay on that base, so the chain's depth drops to two. Only the keys
// written since the base was built are visited — the base's whole keyspace
// is never copied — so the temporary allocation a deep chain costs tracks
// recently touched keys, not live keys. The merged overlay is a fresh map
// and the base is shared immutable state, so views already published stay
// untouched.
func (v *view) collapse() *view {
	base := v
	for base.base != nil {
		base = base.base
	}
	if base == v {
		return v // already flat
	}
	merged := newView(base)
	seen := make(map[string]struct{})
	for cur := v; cur != base; cur = cur.base {
		for k, n := range cur.keys {
			if _, ok := seen[k]; ok {
				continue
			}
			seen[k] = struct{}{}
			merged.keys[k] = n
		}
	}
	return merged
}

input.new_string:
// mergeRuns merges the run ending at v with the run directly below while
// the lower run is no larger, keeping run sizes geometrically decreasing
// from the flat base upward. The flat base itself (base == nil) is never
// merged into — copying it would cost the whole live keyspace. Each merge
// allocates one fresh map sized by the two runs combined and leaves both
// source runs untouched, so the temporary allocation tracks only the keys
// those runs cover, and every view already published stays valid.
func mergeRuns(v *view) *view {
	for v.base != nil && v.base.base != nil && v.base.span <= v.span {
		lower := v.base
		merged := &view{
			keys: make(map[string]*node, len(lower.keys)+len(v.keys)),
			base: lower.base,
			span: lower.span + v.span,
		}
		for k, n := range lower.keys {
			merged.keys[k] = n
		}
		for k, n := range v.keys { // the upper run shadows on conflict
			merged.keys[k] = n
		}
		v = merged
	}
	return v
}

